import java.io.*; public class Main { static long count(File f)throws IOException { long n=0; try(BufferedReader r=new BufferedReader(new FileReader(f))){while(r.readLine()!=null)n++;} return n;} public static void main(String[] a)throws Exception {System.out.println("50 MiB byte-at-a-time: about 52,428,800 read calls.");System.out.println("BufferedReader streams blocks; O(file) time, O(buffer + line) extra space."); if(a.length>0)System.out.println("Lines="+count(new File(a[0]))); }}